 return {orders,router,lookups,get writes(){return writes}};
}
function request(app:ReturnType<typeof fixture>, token:string|undefined='Bearer secret-X', id='probe-unique',body?:unknown){return app.router.handle({method:'POST',path:`/orders/${id}/cancel`,headers:{authorization:token},body})}
